        var list = new ReadOnlySpan<kinfo_proc>(entries, numProcesses);
        var pids = new int[numProcesses];

        // walk through process list and skip kernel threads
        int idx = 0;
        for (int i = 0; i < list.Length; i++)
        {
            if (list[i].p_ppid == 0)
